9	import Combine
10	import Compound
11	import SwiftUI
12	
13	struct HomeScreenRecoveryKeyConfirmationBanner: View {
14	    enum State { case setUpRecovery, recoveryOutOfSync }
15	    let state: State
16	    var context: HomeScreenViewModel.Context
17	    
18	    var title: String {
19	        switch state {
20	        case .setUpRecovery: L10n.bannerSetUpRecoveryTitle
21	        case .recoveryOutOfSync: L10n.confirmRecoveryKeyBannerTitle
22	        }
23	    }
24	
25	    var message: String {
26	        switch state {
27	        case .setUpRecovery: L10n.bannerSetUpRecoveryContent
28	        case .recoveryOutOfSync: L10n.confirmRecoveryKeyBannerMessage
29	        }
30	    }
31	
32	    var actionTitle: String {
33	        switch state {
34	        case .setUpRecovery: L10n.bannerSetUpRecoverySubmit
35	        case .recoveryOutOfSync: L10n.confirmRecoveryKeyBannerPrimaryButtonTitle
36	        }
37	    }
38	
39	    var primaryAction: HomeScreenViewAction {
40	        switch state {
41	        case .setUpRecovery: .setupRecovery
42	        case .recoveryOutOfSync: .confirmRecoveryKey
43	        }
44	    }
45	    
46	    var body: some View {
47	        VStack(spacing: 16) {
48	            content
49	            buttons
50	        }
51	        .padding(16)
52	        .background(Color.compound.bgSubtleSecondary)
53	        .cornerRadius(14)
54	        .padding(.horizontal, 16)
55	    }
56	    
57	    var content: some View {
58	        VStack(alignment: .leading, spacing: 4) {
59	            HStack(alignment: .firstTextBaseline, spacing: 16) {
60	                Text(title)
61	                    .font(.compound.bodyLGSemibold)
62	                    .foregroundColor(.compound.textPrimary)
63	                    .frame(maxWidth: .infinity, alignment: .leading)
64	                
65	                if state == .setUpRecovery {
66	                    Button {
67	                        context.send(viewAction: .skipRecoveryKeyConfirmation)
68	                    } label: {
69	                        Image(systemName: "xmark")
70	                            .foregroundColor(.compound.iconSecondary)
71	                            .frame(width: 12, height: 12)
72	                    }
73	                }
74	            }
75	            
76	            Text(message)
77	                .font(.compound.bodyMD)
78	                .foregroundColor(.compound.textSecondary)
79	        }
80	    }
81	    
82	    var buttons: some View {
83	        VStack(spacing: 16) {
84	            Button {
85	                context.send(viewAction: primaryAction)
86	            } label: {
87	                Text(actionTitle)
88	                    .frame(maxWidth: .infinity)
89	            }
90	            .buttonStyle(.compound(.primary, size: .medium))
91	            .accessibilityIdentifier(A11yIdentifiers.homeScreen.recoveryKeyConfirmationBannerContinue)
92	            
93	            if state == .recoveryOutOfSync {
94	                Button {
95	                    context.send(viewAction: .resetEncryption)
96	                } label: {
97	                    Text(L10n.confirmRecoveryKeyBannerSecondaryButtonTitle)
98	                        .frame(maxWidth: .infinity)
99	                }
100	                .buttonStyle(.compound(.tertiary, size: .medium))
101	            }
102	        }
103	    }
104	}
