106	struct HomeScreenRecoveryKeyConfirmationBanner_Previews: PreviewProvider, TestablePreview {
107	    static let viewModel = makeViewModel()
108	    
109	    static var previews: some View {
110	        HomeScreenRecoveryKeyConfirmationBanner(state: .setUpRecovery,
111	                                                context: viewModel.context)
112	            .previewDisplayName("Set up recovery")
113	        HomeScreenRecoveryKeyConfirmationBanner(state: .recoveryOutOfSync,
114	                                                context: viewModel.context)
115	            .previewDisplayName("Out of sync")
116	    }
117	    
118	    static func makeViewModel() -> HomeScreenViewModel {
119	        let clientProxy = ClientProxyMock(.init(userID: "@alice:example.com",
120	                                                roomSummaryProvider: RoomSummaryProviderMock(.init(state: .loading))))
121	        
122	        let userSession = UserSessionMock(.init(clientProxy: clientProxy))
123	        
124	        return HomeScreenViewModel(userSession: userSession,
125	                                   selectedRoomPublisher: CurrentValueSubject<String?, Never>(nil).asCurrentValuePublisher(),
126	                                   appSettings: ServiceLocator.shared.settings,
127	                                   analyticsService: ServiceLocator.shared.analytics,
128	                                   notificationManager: NotificationManagerMock(),
129	                                   userIndicatorController: ServiceLocator.shared.userIndicatorController)
130	    }
131	}
