12	
13	struct SecureBackupRecoveryKeyScreen: View {
14	    @Bindable var context: SecureBackupRecoveryKeyScreenViewModel.Context
15	    @FocusState private var focused
16	    private let textFieldIdentifier = "textFieldIdentifier"
17	    
18	    var body: some View {
19	        FullscreenDialog {
20	            ScrollViewReader { reader in
21	                mainContent
22	                    .onChange(of: focused) { _, newValue in
23	                        guard newValue == true else { return }
24	                        reader.scrollTo(textFieldIdentifier)
25	                    }
26	            }
27	        } bottomContent: {
28	            footer
29	        }
30	        .toolbar { toolbar }
31	        .toolbar(.visible, for: .navigationBar)
32	        .background()
33	        .backgroundStyle(.compound.bgCanvasDefault)
34	        .interactiveDismissDisabled()
35	        .alert(item: $context.alertInfo)
36	    }
37	    
38	    private var mainContent: some View {
39	        VStack(spacing: 48) {
40	            switch context.viewState.mode {
41	            case .setupRecovery, .changeRecovery:
42	                header
43	                generateRecoveryKeySection
44	            case .fixRecovery:
45	                header
46	                confirmRecoveryKeySection
47	            case .unknown:
48	                header
49	            }
50	        }
51	    }
52	    
53	    private var header: some View {
54	        VStack(spacing: 16) {
55	            BigIcon(icon: \.keySolid)
56	            
57	            Text(context.viewState.title)
58	                .foregroundColor(.compound.textPrimary)
59	                .font(.compound.headingMDBold)
60	                .multilineTextAlignment(.center)
61	            
62	            if let subtitle = context.viewState.subtitle {
63	                Text(subtitle)
64	                    .foregroundColor(.compound.textSecondary)
65	                    .font(.compound.bodyMD)
66	                    .multilineTextAlignment(.center)
67	            }
68	        }
69	    }
70	    
71	    @ViewBuilder
72	    private var footer: some View {
73	        switch context.viewState.mode {
74	        case .setupRecovery, .changeRecovery:
75	            recoveryCreatedActionButtons
76	        case .fixRecovery:
77	            incompleteVerificationActionButtons
78	        case .unknown:
79	            EmptyView()
80	        }
81	    }
82	    
83	    private var incompleteVerificationActionButtons: some View {
84	        VStack(spacing: 16) {
85	            Button {
86	                context.send(viewAction: .confirmKey)
87	            } label: {
88	                Text(L10n.actionConfirm)
89	            }
90	            .buttonStyle(.compound(.primary))
91	            .disabled(context.confirmationRecoveryKey.isEmpty)
92	            .accessibilityIdentifier(A11yIdentifiers.secureBackupRecoveryKeyScreen.confirm)
93	        }
94	    }
95	    
96	    private var recoveryCreatedActionButtons: some View {
97	        VStack(spacing: 16) {
98	            if let recoveryKey = context.viewState.recoveryKey {
99	                ShareLink(item: recoveryKey) {
100	                    Label(L10n.screenRecoveryKeySaveAction, icon: \.download)
